use Illuminate\Http\Request;use Illuminate\Http\Resources\Json\JsonResource;
class BookingResource extends JsonResource { public function toArray(Request $request):array{return ['id'=>$this->id,'reference'=>$this->reference,'customer'=>$this->whenLoaded('customer',fn()=>['id'=>$this->customer?->id,'full_name'=>$this->customer?->full_name,'phone'=>$this->customer?->phone,'email'=>$this->customer?->email,'cnic'=>$this->customer?->cnic,'address'=>$this->customer?->address]),'vehicle'=>$this->whenLoaded('vehicle',fn()=>['id'=>$this->vehicle?->id,'name'=>$this->vehicle?->name,'slug'=>$this->vehicle?->slug]),'pickup_location'=>$this->pickupLocation?->name ?: $this->pickup_location_text,'dropoff_location'=>$this->dropoffLocation?->name ?: $this->dropoff_location_text,'pickup_at'=>$this->pickup_at?->toIso8601String(),'return_at'=>$this->return_at?->toIso8601String(),'handover_at'=>$this->handover_at?->toIso8601String(),'actual_return_at'=>$this->actual_return_at?->toIso8601String(),'handover_odometer'=>$this->handover_odometer,'return_odometer'=>$this->return_odometer,'rental_type'=>$this->rental_type,'duration_days'=>$this->duration_days,'base_price'=>$this->base_price,'additional_charges'=>$this->additional_charges,'discount'=>$this->discount,'total_price'=>$this->total_price,'deposit'=>$this->deposit,'payment_status'=>$this->payment_status,'status'=>$this->status,'customer_notes'=>$this->customer_notes,'admin_notes'=>$this->admin_notes,'status_history'=>$this->whenLoaded('statusHistory'),'created_at'=>$this->created_at?->toIso8601String()];} }
